#include <linux/errno.h>
#include <linux/fs.h>
#include <linux/sysctl.h>

int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header = NULL;
    int ret = 0;

    /* Retrieve the header for the sysctl directory */
    header = sysctl_get_dir_header(file);
    if (IS_ERR_OR_NULL(header)) {
        return PTR_ERR(header);
    }

    /* Handle '.' and '..' entries */
    ret = dir_emit_dot(ctx);
    if (ret < 0) {
        sysctl_put_dir_header(header);
        return ret;
    }

    ret = dir_emit_dotdot(ctx);
    if (ret < 0) {
        sysctl_put_dir_header(header);
        return ret;
    }

    /* Iterate through the entries in the sysctl directory */
    while (1) {
        struct sysctl_entry *entry = sysctl_get_next_entry(header);
        if (IS_ERR(entry)) {
            ret = PTR_ERR(entry);
            break;
        }

        if (entry == NULL) {
            break;
        }

        ret = sysctl_scan_entry(entry, ctx);
        if (ret < 0) {
            break;
        }
    }

    sysctl_put_dir_header(header);
    return ret >= 0 ? 0 : ret;
}
